import AppKit
import SwiftUI

/// GitHub's own icons for what is GitHub's: pull requests, branches,
/// repositories, checks, reviews. macOS controls keep SF Symbols. Tinted
/// like text with `foregroundStyle`.
struct Octicon: View {
  let name: Name
  var size: CGFloat = 13

  init(_ name: Name, size: CGFloat = 13) {
    self.name = name
    self.size = size
  }

  var body: some View {
    Image(nsImage: name.image).renderingMode(.template).resizable().scaledToFit()
      .frame(width: size, height: size)
  }

