    case gitBranch = "git-branch"
    case home = "home"
    case fileDirectory = "file-directory"
    case repo = "repo"
    case server = "server"
    case lock = "lock"
    case checkCircleFill = "check-circle-fill"
    case xCircleFill = "x-circle-fill"
    case dotFill = "dot-fill"
    case skip = "skip"
    case check = "check"
    case fileDiff = "file-diff"
    case comment = "comment"
    case circleSlash = "circle-slash"
    case eye = "eye"
    case checklist = "checklist"
    case tag = "tag"
    case book = "book"
    case person = "person"

    /// Drawn from its SVG, once.
    @MainActor var image: NSImage {
      if let image = Self.images[self] { return image }
      let image = NSImage(data: Data(svg.utf8)) ?? NSImage()
      image.isTemplate = true
      Self.images[self] = image
      return image
